const BOARD_SIZE = 15
const CELL_COUNT = BOARD_SIZE * BOARD_SIZE

// Precompute 8 D4 symmetry maps and their inverses on 15x15 (idx = y * 15 + x)
const D4_FWD = []
const D4_INV = []

function transformXY(x, y, t) {
  const n = BOARD_SIZE - 1
  switch (t) {
    case 0:
      return [x, y]
    case 1:
      return [n - y, x]
    case 2:
      return [n - x, n - y]
    case 3:
      return [y, n - x]
    case 4:
      return [n - x, y]
    case 5:
      return [n - y, n - x]
    case 6:
      return [x, n - y]
    case 7:
      return [y, x]
  }
}

for (let t = 0; t < 8; t++) {
  const fwd = new Uint8Array(CELL_COUNT)
  const inv = new Uint8Array(CELL_COUNT)
  for (let y = 0; y < BOARD_SIZE; y++) {
    for (let x = 0; x < BOARD_SIZE; x++) {
      const src = y * BOARD_SIZE + x
      const [tx, ty] = transformXY(x, y, t)
      const dst = ty * BOARD_SIZE + tx
      fwd[src] = dst
      inv[dst] = src
    }
  }
  D4_FWD.push(fwd)
  D4_INV.push(inv)
}

let db = null
let loadPromise = null
const progressListeners = new Set()

export async function loadRenjunetDB(onProgress) {
  if (onProgress) {
    if (db) onProgress(1)
    else progressListeners.add(onProgress)
  }
  if (db) return db
  if (loadPromise) return loadPromise

  const notify = (p) => {
    for (const cb of progressListeners) cb(p)
  }

  loadPromise = (async () => {
    const base = `${process.env.BASE_URL}renjunet/`
    const [metaRes, binRes] = await Promise.all([
      fetch(`${base}renjunet_meta.json.gz`),
      fetch(`${base}renjunet_games.bin.gz`),
    ])
    if (!metaRes.ok || !binRes.ok) {
      throw new Error(`Failed to load RenjuNet book (${metaRes.status}/${binRes.status})`)
    }

    const total = Number(binRes.headers.get('content-length')) || 3990082
    let gzBytes
    if (binRes.body && binRes.body.getReader) {
      const reader = binRes.body.getReader()
      const chunks = []
      let received = 0
      while (true) {
        const { done, value } = await reader.read()
        if (done) break
        chunks.push(value)
        received += value.byteLength
        notify(Math.min(received / total, 0.99))
      }
      gzBytes = new Uint8Array(received)
      let offset = 0
      for (const c of chunks) {
        gzBytes.set(c, offset)
        offset += c.byteLength
      }
    } else {
      gzBytes = new Uint8Array(await binRes.arrayBuffer())
    }

    const decompress = async (stream) => {
      const ds = new DecompressionStream('gzip')
      return new Response(stream.pipeThrough(ds)).arrayBuffer()
    }

    const [metaBuf, buf] = await Promise.all([
      decompress(metaRes.body),
      decompress(new Blob([gzBytes]).stream()),
    ])
    const meta = JSON.parse(new TextDecoder().decode(metaBuf))
    const view = new DataView(buf)
    const magic = view.getUint32(0, true)
    if (magic !== 0x524e4a32) {
      throw new Error('Invalid RenjuNet binary header')
    }
    const gameCount = view.getUint32(4, true)
    const bytes = new Uint8Array(buf)

    const bOff = 8
    const wOff = bOff + gameCount * 2
    const tOff = wOff + gameCount * 2
    const rOff = tOff + gameCount * 2
    const resOff = rOff + gameCount
    const mcOff = resOff + gameCount
    const mvOff = mcOff + gameCount

    const blackIdx = new Uint16Array(buf, bOff, gameCount)
    const whiteIdx = new Uint16Array(buf, wOff, gameCount)
    const tourIdx = new Uint16Array(buf, tOff, gameCount)
    const ruleId = bytes.subarray(rOff, resOff)
    const result = bytes.subarray(resOff, mcOff)
    const moveCount = bytes.subarray(mcOff, mvOff)
    const moveOffset = new Uint32Array(gameCount)

    let pos = mvOff
    for (let g = 0; g < gameCount; g++) {
      moveOffset[g] = pos
      pos += moveCount[g]
    }

    const ruleCat = new Uint8Array(256)
    if (meta.ruleCategories) {
      for (const [rid, cat] of Object.entries(meta.ruleCategories)) {
        ruleCat[Number(rid)] = cat
      }
    }

    db = {
      meta,
      ruleCat,
      gameCount,
      bytes,
      blackIdx,
      whiteIdx,
      tourIdx,
      ruleId,
      result,
      moveCount,
      moveOffset,
    }
    notify(1)
    progressListeners.clear()
    return db
  })().catch((err) => {
    loadPromise = null
    progressListeners.clear()
    throw err
  })

  return loadPromise
}

export function queryRenjunetPosition(
  position,
  { normalizeOrder = true, maxGames = 100, category = 1 } = {}
) {
  if (!db) return null

  const k = position.length
  const sideToMove = k % 2 === 0 ? 1 : 2 // 1 = BLACK, 2 = WHITE
  const { gameCount, bytes, blackIdx, whiteIdx, tourIdx, ruleId, ruleCat, result, moveCount, moveOffset, meta } = db

  const boards = []
  const boardsPrev = []
  const seqs = []
  for (let t = 0; t < 8; t++) {
    const fwd = D4_FWD[t]
    if (normalizeOrder) {
      const b = new Uint8Array(CELL_COUNT)
      for (let i = 0; i < k; i++) {
        const idx = position[i][1] * BOARD_SIZE + position[i][0]
        b[fwd[idx]] = (i & 1) + 1
      }
      boards.push(b)
      if (k > 0) {
        const bp = new Uint8Array(CELL_COUNT)
        for (let i = 0; i < k - 1; i++) {
          const idx = position[i][1] * BOARD_SIZE + position[i][0]
          bp[fwd[idx]] = (i & 1) + 1
        }
        boardsPrev.push(bp)
      }
    } else {
      const s = new Uint8Array(k)
      for (let i = 0; i < k; i++) {
        const idx = position[i][1] * BOARD_SIZE + position[i][0]
        s[i] = fwd[idx]
      }
      seqs.push(s)
    }
  }

  // Precompute canonical next-move map under the stabilizer subgroup Stab(s) of D4
  // so that D4-equivalent candidate moves (s, m) are merged together.
  const stabTransforms = [0]
  for (let t = 1; t < 8; t++) {
    let same = true
    if (normalizeOrder) {
      const b0 = boards[0]
      const bt = boards[t]
      for (let idx = 0; idx < CELL_COUNT; idx++) {
        if (b0[idx] !== bt[idx]) {
          same = false
          break
        }
      }
    } else {
      const s0 = seqs[0]
      const st = seqs[t]
      for (let i = 0; i < k; i++) {
        if (s0[i] !== st[i]) {
          same = false
          break
        }
      }
    }
    if (same) stabTransforms.push(t)
  }

  const hasVertAxis = stabTransforms.includes(4)
  const hasSlashAxis = stabTransforms.includes(5)
  const hasHorizAxis = stabTransforms.includes(6)
  const hasBackslashAxis = stabTransforms.includes(7)

  const isBetterCoord = (a, b) => {
    const ax = a % BOARD_SIZE
    const ay = Math.floor(a / BOARD_SIZE)
    const bx = b % BOARD_SIZE
    const by = Math.floor(b / BOARD_SIZE)
    if (hasVertAxis && hasSlashAxis) {
      // Both main axes present (e.g. [h8]): place in upper-right region (x >= 7, y <= 7)
      const aUR = ax >= 7 && ay <= 7 ? 1 : 0
      const bUR = bx >= 7 && by <= 7 ? 1 : 0
      if (aUR !== bUR) return aUR > bUR
      if (ay !== by) return ay < by
      return ax > bx
    }
    if (hasVertAxis) {
      // Vertical center axis (x = 7): place on right (x >= 7)
      const aR = ax >= 7 ? 1 : 0
      const bR = bx >= 7 ? 1 : 0
      if (aR !== bR) return aR > bR
      return false
    }
    if (hasHorizAxis) {
      // Horizontal center axis (y = 7, 90° CW rotation of x = 7): y >= 7
      const aB = ay >= 7 ? 1 : 0
      const bB = by >= 7 ? 1 : 0
      if (aB !== bB) return aB > bB
      return false
    }
    if (hasSlashAxis) {
      // Main '/' diagonal axis (x + y = 14): place on lower-right (x + y >= 14)
      const aLR = ax + ay >= 14 ? 1 : 0
      const bLR = bx + by >= 14 ? 1 : 0
      if (aLR !== bLR) return aLR > bLR
      return false
    }
    if (hasBackslashAxis) {
      // Anti-diagonal '\' axis (x = y, 90° CW rotation of x + y = 14): y >= x
      const aLL = ay >= ax ? 1 : 0
      const bLL = by >= bx ? 1 : 0
      if (aLL !== bLL) return aLL > bLL
      return false
    }
    // Not symmetric across any reflection axis -> keep original
    return false
  }

  const canonBoardKey = (boardsArr, extraIdx, extraColor) => {
    let bestKey = null
    for (let t = 0; t < 8; t++) {
      const bt = boardsArr[t]
      const mapped = extraIdx >= 0 ? D4_FWD[t][extraIdx] : -1
      let key = ''
      for (let c = 0; c < CELL_COUNT; c++) {
        const v = c === mapped ? extraColor : bt[c]
        if (v !== 0) key += String.fromCharCode(48 + v, 32 + c)
      }
      if (bestKey === null || key < bestKey) bestKey = key
    }
    return bestKey
  }

  const canonNextIdx = new Uint8Array(CELL_COUNT)
  let prevValidNext = null
  let lastMoveIdx = -1
  if (normalizeOrder) {
    // Group candidate moves by the canonical D4 board state of (s ∪ {m}),
    // so transpositions with different move orders that yield D4-equivalent
    // resulting boards are merged into the same equivalence class.
    const classRep = new Map()
    const idxKeys = new Array(CELL_COUNT)
    for (let idx = 0; idx < CELL_COUNT; idx++) {
      if (boards[0][idx] !== 0) {
        canonNextIdx[idx] = idx
        continue
      }
      const bestKey = canonBoardKey(boards, idx, sideToMove)
      idxKeys[idx] = bestKey
      const prev = classRep.get(bestKey)
      if (prev === undefined) {
        classRep.set(bestKey, idx)
      } else if (isBetterCoord(idx, prev)) {
        classRep.set(bestKey, idx)
      }
    }
    for (let idx = 0; idx < CELL_COUNT; idx++) {
      if (boards[0][idx] === 0) canonNextIdx[idx] = classRep.get(idxKeys[idx])
    }

    if (k > 0) {
      lastMoveIdx = position[k - 1][1] * BOARD_SIZE + position[k - 1][0]
      const lastColor = ((k - 1) & 1) + 1
      const targetPrevKey = canonBoardKey(boardsPrev, lastMoveIdx, lastColor)
      prevValidNext = new Uint8Array(CELL_COUNT)
      for (let idx = 0; idx < CELL_COUNT; idx++) {
        if (boardsPrev[0][idx] === 0 && canonBoardKey(boardsPrev, idx, lastColor) === targetPrevKey) {
          prevValidNext[idx] = 1
        }
      }
    }
  } else {
    for (let idx = 0; idx < CELL_COUNT; idx++) {
      let best = idx
      for (let j = 0; j < stabTransforms.length; j++) {
        const mapped = D4_FWD[stabTransforms[j]][idx]
        if (isBetterCoord(mapped, best)) best = mapped
      }
      canonNextIdx[idx] = best
    }
  }

  let total = 0
  let blackWins = 0
  let draws = 0
  let whiteWins = 0
  let unknown = 0

  const nextMap = new Map()
  const matchedGames = []

  for (let g = gameCount - 1; g >= 0; g--) {
    if (category != null && ruleCat[ruleId[g]] !== category) continue
    const mc = moveCount[g]
    if (mc < k) continue

    const off = moveOffset[g]
    let posT = -1

    if (k === 0) {
      posT = 0
    } else if (normalizeOrder) {
      for (let t = 0; t < 8; t++) {
        const bp = boardsPrev[t]
        let ok = true
        for (let i = 0; i < k - 1; i++) {
          if (bp[bytes[off + i]] !== (i & 1) + 1) {
            ok = false
            break
          }
        }
        if (ok && prevValidNext[D4_INV[t][bytes[off + k - 1]]] === 1) {
          posT = t
          break
        }
      }
    } else {
      for (let t = 0; t < 8; t++) {
        const s = seqs[t]
        let ok = true
        for (let i = 0; i < k; i++) {
          if (bytes[off + i] !== s[i]) {
            ok = false
            break
          }
        }
        if (ok) {
          posT = t
          break
        }
      }
    }

    const res = result[g]

    if (posT !== -1) {
      total++
      if (res === 2) blackWins++
      else if (res === 1) draws++
      else if (res === 0) whiteWins++
      else unknown++

      if (matchedGames.length < maxGames) {
        const tInfo = meta.tournaments[tourIdx[g]] || ['', '']
        matchedGames.push({
          gameIdx: g,
          transform: posT,
          black: meta.players[blackIdx[g]] || '?',
          white: meta.players[whiteIdx[g]] || '?',
          tournament: tInfo[0] || '',
          year: tInfo[1] || '',
          rule: meta.rules[String(ruleId[g])] || String(ruleId[g]),
          result: res,
          moveCount: mc,
          nextPos:
            mc > k
              ? [
                  D4_INV[posT][bytes[off + k]] % BOARD_SIZE,
                  Math.floor(D4_INV[posT][bytes[off + k]] / BOARD_SIZE),
                ]
              : null,
        })
      }
    }

    if (mc > k) {
      let nextT = posT
      if (normalizeOrder && k > 0) {
        if (posT === -1 || D4_INV[posT][bytes[off + k - 1]] !== lastMoveIdx) {
          nextT = -1
          for (let t = 0; t < 8; t++) {
            const b = boards[t]
            let ok = true
            for (let i = 0; i < k; i++) {
              if (b[bytes[off + i]] !== (i & 1) + 1) {
                ok = false
                break
              }
            }
            if (ok) {
              nextT = t
              break
            }
          }
        }
      }

      if (nextT !== -1) {
        const nextIdx = canonNextIdx[D4_INV[nextT][bytes[off + k]]]
        let entry = nextMap.get(nextIdx)
        if (!entry) {
          entry = {
            idx: nextIdx,
            pos: [nextIdx % BOARD_SIZE, Math.floor(nextIdx / BOARD_SIZE)],
            count: 0,
            blackWins: 0,
            draws: 0,
            whiteWins: 0,
            scoredCount: 0,
            moverScoreSum: 0,
          }
          nextMap.set(nextIdx, entry)
        }
        entry.count++
        if (res === 2) {
          entry.blackWins++
          entry.scoredCount++
          entry.moverScoreSum += sideToMove === 1 ? 1 : 0
        } else if (res === 1) {
          entry.draws++
          entry.scoredCount++
          entry.moverScoreSum += 0.5
        } else if (res === 0) {
          entry.whiteWins++
          entry.scoredCount++
          entry.moverScoreSum += sideToMove === 2 ? 1 : 0
        }
      }
    }
  }

  const nextMoves = Array.from(nextMap.values())
    .map((e) => ({
      ...e,
      scoreRate: e.scoredCount > 0 ? e.moverScoreSum / e.scoredCount : null,
    }))
    .sort((a, b) => b.count - a.count)

  const scoredTotal = blackWins + draws + whiteWins
  const totalScoreSum =
    sideToMove === 1 ? blackWins + 0.5 * draws : whiteWins + 0.5 * draws

  return {
    sideToMove,
    total,
    blackWins,
    draws,
    whiteWins,
    unknown,
    scoreRate: scoredTotal > 0 ? totalScoreSum / scoredTotal : null,
    nextMoves,
    games: matchedGames,
  }
}

export const RENJU_RULE_ZH = {
  Classic: '五手两打',
  Taraguchi: '塔拉山口',
  Sakata: '坂田',
  Tarannikov: '塔拉尼科夫',
  Yamaguchi: '山口',
  Jonsson: '琼森',
  Rejection: '拒绝',
  Experimental: '实验',
  Soosyrv: '索索夫',
  LianHuan: '连换',
  'Soosyrv-10': '索索夫-10',
  'LianHuan-5': '连换-5',
  'Taraguchi-7': '塔拉山口-7',
  'Super Sakata': '超级坂田',
  'Soosyrv-5': '索索夫-5',
  'Yamasyrv-5': '山索-5',
  'Soosyrv-7': '索索夫-7',
  'Yamasyrv-7': '山索-7',
  'Yamasyrv-8': '山索-8',
  'Soosyrv-8 (with indulgence)': '索索夫-8(宽容)',
  'Soosyrv-8': '索索夫-8',
  'Taraguchi-10': '塔拉山口-10',
  'Swap-5 free': '五手连换',
  'Super Taraguchi-10': '超级塔拉山口-10',
  'Gomoku - Pro': 'Pro',
  'Gomoku - Swap 2': '无禁二次交换',
  'Gomoku - Experimental': '无禁实验',
  'Gomoku - Swap': '无禁一手交换',
}

export function formatRenjuRule(rule) {
  if (!rule) return '-'
  return RENJU_RULE_ZH[rule] || rule
}

export function getRenjunetGameMoves(gameIdx, transform = 0) {
  if (!db || gameIdx < 0 || gameIdx >= db.gameCount) return []
  const off = db.moveOffset[gameIdx]
  const mc = db.moveCount[gameIdx]
  const inv = D4_INV[transform] || D4_INV[0]
  const moves = []
  for (let i = 0; i < mc; i++) {
    const idx = inv[db.bytes[off + i]]
    moves.push([idx % BOARD_SIZE, Math.floor(idx / BOARD_SIZE)])
  }
  return moves
}
